import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.9ngYh_O2.js";const u=JSON.parse('{"title":"学习路线","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/roadmap.md","filePath":"getting-started/roadmap.md","lastUpdated":1788503940000}'),r={name:"getting-started/roadmap.md"};function n(s,t,i,c,l,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h1><p>旧入门手册只提供已确认的系统总览和分阶段思路；其中的用户路径、软件状态和硬件快照不自动继承。</p><h2 id="总体数据流" tabindex="-1">总体数据流 <a class="header-anchor" href="#总体数据流" aria-label="Permalink to &quot;总体数据流&quot;">​</a></h2><p>【推测】现阶段先用下面的抽象理解各层位置，具体话题、坐标系、频率和接口必须在对应阶段验证。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传感器 → VINS/VIO → 地图 → EGO-Planner → 控制器 → PX4 → 飞行器</span></span></code></pre></div><h2 id="阶段与验收" tabindex="-1">阶段与验收 <a class="header-anchor" href="#阶段与验收" aria-label="Permalink to &quot;阶段与验收&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>进入下一阶段前的证据</th></tr></thead><tbody><tr><td>1. ROS 2 基础</td><td>理解节点、话题、参数、Launch、TF、Bag</td><td>【待验证】能检查最小 ROS 图并记录、回放数据。</td></tr><tr><td>2. EGO-Planner</td><td>建立 Humble 环境并运行单机规划仿真</td><td>✅【运行验证】已完成：20 包编译成功，8 节点齐全，<code>pos_cmd</code> 100 Hz，RViz 硬件渲染，状态机走通。</td></tr><tr><td>2.5 读懂源码</td><td>能定位任意行为对应的代码，并预测自己改动的效果</td><td>🔄 进行中：架构、入口、初始化、状态机、规划三步已成文，见<a href="/drone-learning-lab/ego-planner/source-reading">第四步：读懂源码</a>；B/C 类文件（<code>traj_server</code>、<code>bspline_optimizer</code>）尚未精读。</td></tr><tr><td>3. VINS / VIO</td><td>先用公开数据集验证定位</td><td>【待验证】轨迹稳定，能定位内参、外参与时间配置。</td></tr><tr><td>4. PX4 SITL</td><td>建立飞控软件在环</td><td>【待验证】完成解锁、起飞、悬停、降落和失效保护检查。</td></tr><tr><td>5. 完整闭环</td><td>感知、定位、规划、控制逐层连接</td><td>【待验证】轨迹可跟踪、障碍可重规划、异常可安全退出。</td></tr><tr><td>6. 真实硬件</td><td>接 RealSense、飞控和机载电脑</td><td>【待验证】先完成无桨与约束场地测试。</td></tr><tr><td>7. 专题</td><td>MuJoCo / Isaac Sim 等</td><td>【待验证】只在主线稳定后选择。</td></tr></tbody></table><h2 id="当前停点" tabindex="-1">当前停点 <a class="header-anchor" href="#当前停点" aria-label="Permalink to &quot;当前停点&quot;">​</a></h2><p>【运行验证】<strong>第 2 阶段已经完成验收</strong>：镜像构建成功（4.84 GB），<code>colcon build</code> 20 个包全部通过，<code>single_run_in_sim.launch.py</code> 起了 8 个节点，闭环 <code>pos_cmd</code> 稳定在 100.002 Hz，RViz 硬件渲染正常，规划状态机在 <code>EXEC_TRAJ ⇄ REPLAN_TRAJ</code> 之间正常循环。详细过程见 <a href="/drone-learning-lab/ego-planner/simulation">第三步：跑通单机仿真</a>。</p><p>现在的里程碑是<strong>系统地读懂 EGO 源码</strong>。已完成的部分写在<a href="/drone-learning-lab/ego-planner/source-reading">第四步：读懂源码</a>：全局架构、目录优先级（A/B/C）、22 行入口、<code>init</code> 的四段结构、七状态状态机的全部迁移条件（带行号）、<code>reboundReplan</code> 三步流水线，以及两个可回滚的小修改练习。</p><p>还没做的：<code>traj_server.cpp</code>（275 行）和 <code>uav_simulator/fake_drone</code>（124 行）这条「轨迹 → 指令 → odom」回路，以及 <code>bspline_optimizer.cpp</code>（1862 行）的优化数学。这两块做完才进入第 3 阶段。</p><div class="warning custom-block"><p class="custom-block-title">明确不做的事</p><p>VINS、PX4 SITL、QGroundControl、RealSense、Isaac Sim、MuJoCo 现在<strong>一个都不装</strong>。理由：主线还没稳，提前铺开只会让排错变得无法定位。等源码读明白、能自己改参数并预测结果之后再往下走。</p></div><h2 id="学习规则" tabindex="-1">学习规则 <a class="header-anchor" href="#学习规则" aria-label="Permalink to &quot;学习规则&quot;">​</a></h2><p>每一步都按“检查 → 修改 → 构建 → 运行 → 验证 → 记录”推进。源码阅读从目录、入口和调用关系开始；每个重要结论保留证据标签，失败则进入排错页。</p>',14)])])}const _=e(r,[["render",n]]);export{u as __pageData,_ as default};
